M1 = []

M1.append(dict(
 n=1, slug="mindset", part="Part 1: Mindset", threat="Threat class: everything",
 title="Mitigation, threat modeling, and defense in depth",
 short="Stop asking 'am I safe?' and start asking what you are protecting, from whom.",
 objective="Swap the question &ldquo;am I safe?&rdquo; for &ldquo;what am I protecting, from whom, and what will I do about it?&rdquo;",
 points=[
  "Perfect security is impossible. The job is to stop the <b>avoidable</b> hacks (phishing, password reuse) and limit the damage from the <b>unavoidable</b> ones (a company you use gets breached).",
  "Five threat-model questions: What do I want to protect? Who do I want to protect it from? How likely is it that I will need to? How bad is it if I fail? How much trouble am I willing to go through to prevent it?",
  "<b>Baseline</b> (most people): password manager, MFA, updates, phishing sense, backups. <b>Elevated</b> (money, a business, a public profile): add security keys, a credit freeze, a locked-down phone number, separate browser profiles. <b>High risk</b> (journalists, activists, anyone targeted by a person who knows them): add strict Signal habits, Lockdown Mode, separate accounts for separate roles, and get specialist help.",
  "<b>Defense in depth:</b> prevent, detect, recover. No single tool does all three.",
  "<b>Least privilege:</b> do daily work from a standard account, not an admin account. Give every app and extension only what it needs.",
  "<b>Herd immunity:</b> your habits protect the people who text, email, and share files with you."],
 myth="I'm not important enough to hack.",
 reality="Most attacks are automated. You get hit because your password was in a leaked list, not because of who you are.",
 demo="Run the Threat Model Builder below, then write your own five-line threat model on an index card.",
 takeaway="Security is a budget of effort. Spend it where the risk is.",
 cards=[("Threat model","A short written answer to: what am I protecting, from whom, how likely is the attack, how bad is the damage, and how much effort will I spend preventing it."),
        ("Defense in depth","Layering prevention, detection, and recovery so that no single failure leaves you exposed."),
        ("Least privilege","Giving every user, app, and extension only the access it needs. Daily work from a standard account is the everyday example."),
        ("Attack surface","Everything an attacker could try to reach: your accounts, apps, extensions, devices, and habits. Smaller is safer.")],
 quiz=[("Which of these is NOT one of the five threat-model questions?",
        ["What do I want to protect?","Who do I want to protect it from?","Which antivirus has the best reviews?","How bad is it if I fail?"],2,"The five questions are about assets, adversaries, likelihood, consequences, and effort. Product reviews are a later step."),
       ("Prevent, detect, and recover together describe which idea?",
        ["Least privilege","Defense in depth","Herd immunity","Zero trust"],1,"Defense in depth means layering protections across all three jobs, since no single tool covers them all."),
       ("Why do daily work from a standard account instead of an admin account?",
        ["It runs faster","Malware that runs as you gets fewer permissions","Admin accounts cannot browse the web","It removes the need for updates"],1,"Least privilege limits the damage if something malicious runs under your account.")],
 widget="threat"))

M1.append(dict(
 n=2, slug="passwords", part="Part 2: Accounts and identity", threat="Threat class: credential theft",
 title="Passwords and password managers",
 short="Kill password reuse. One passphrase, one manager.",
 objective="Kill password reuse.",
 points=[
  "Reuse is the root problem. One breached site plus one reused password means every account sharing it is compromised. Attackers replay leaked passwords on other sites automatically. That is called credential stuffing.",
  "Use a password manager: <b>Bitwarden</b> (free tier covers the job), <b>1Password</b>, or <b>KeePassXC</b> (local file, no cloud). Skip LastPass: it suffered a serious breach in 2022 that exposed customers' encrypted vault backups.",
  "The master password is a <b>passphrase</b>: several random words you can pronounce and remember. Generate it with dice or the manager. Never reuse it anywhere.",
  "Do not rotate passwords on a schedule. Change one after a breach, a theft, or a phishing slip.",
  "The manager flags reused and breached passwords. Run that report on day one.",
  "Passwords saved in the browser beat reuse and lose to a real manager."],
 myth="A password with symbols and numbers is the strong one.",
 reality="Length and uniqueness beat complexity. A manager removes the debate because you never type or reuse a password.",
 demo="Check an instructor throwaway address at haveibeenpwned.com. Then play with the passphrase math calculator below.",
 takeaway="You do not need a better memory. You need a manager and one strong passphrase.",
 cards=[("Credential stuffing","Automatically trying passwords leaked from one site on many other sites."),
        ("Password manager","An app that creates, stores, and fills unique passwords behind one strong master passphrase."),
        ("Passphrase","Several random words used as a password. Long, memorable, and strong when the words are truly random."),
        ("Data breach","When a company's stored user data is stolen. Your risk depends on whether the stolen password was unique.")],
 quiz=[("A site you use is breached and you reused that password. What is the main danger?",
        ["Only that one site is affected","Every account that shares the password is at risk","Your computer gets a virus","Nothing, passwords are hashed"],1,"Attackers try leaked passwords everywhere. Unique passwords contain the damage."),
       ("What makes a good master password?",
        ["Your birthday with symbols added","A short complex string you change monthly","A long passphrase of random words, used nowhere else","The same password you use for email"],2,"A random multi-word passphrase is strong and memorable. It must be unique."),
       ("What is the current advice on changing passwords?",
        ["Change them every 30 days","Change them only after a breach, theft, or slip","Never change them","Change them every year on a schedule"],1,"Forced rotation leads to weaker, predictable passwords. Change when there is a reason.")],
 widget="entropy"))

M1.append(dict(
 n=3, slug="mfa", part="Part 2: Accounts and identity", threat="Threat class: account takeover",
 title="MFA, passkeys, and security keys",
 short="Every important account gets a second factor better than a text message.",
 objective="Every important account gets a second factor better than a text message.",
 points=[
  "<b>Ranking, best to worst.</b> 1: passkeys and hardware security keys (YubiKey, Titan), which are phishing-resistant because there is nothing to type into a fake site. 2: an authenticator app (TOTP codes). 3: SMS text codes, the weakest because of SIM swapping.",
  "Authenticator options: Ente Auth, Aegis (Android), 2FAS, Microsoft Authenticator. Google Authenticator works, but its cloud sync is not end-to-end encrypted. Skip Authy: the desktop apps are gone and there is no export.",
  "Turn it on first for email, your Apple or Google account, banking, the password manager, social media, and your phone carrier account.",
  "Plan for loss. Buy two security keys, or pair one key with an authenticator app, and store printed recovery codes somewhere safe and offline. Most lockouts are self-inflicted.",
  "<b>MFA fatigue:</b> never approve a prompt you did not start. A surprise prompt means someone already has your password."],
 myth="MFA makes me unhackable.",
 reality="Live phishing sites can relay codes in real time. Only passkeys and security keys resist that.",
 demo="Set up a passkey on a Google or Microsoft account live. Then open the recovery-code page and talk about where you would store the codes.",
 takeaway="Passkey or key first, app second, SMS only when nothing else exists.",
 cards=[("MFA","Multi-factor authentication: proving who you are with something beyond a password."),
        ("Passkey","A phishing-resistant login that replaces the password with a cryptographic key stored on your device."),
        ("TOTP","Time-based one-time password. The six-digit code an authenticator app shows and rotates every 30 seconds."),
        ("SIM swapping","Tricking a carrier into moving your phone number to the attacker's SIM so they receive your text codes.")],
 quiz=[("Which second factor is phishing-resistant?",
        ["SMS code","Authenticator app code","Security key or passkey","Email code"],2,"Keys and passkeys are bound to the real site, so a lookalike site cannot use them."),
       ("Why is SMS the weakest MFA option?",
        ["Texts are slow","SIM swapping can redirect your messages","Phones cannot receive codes abroad","Codes are too short"],1,"If the attacker controls your number they receive your codes."),
       ("You get a login approval prompt you did not trigger. Best response?",
        ["Approve it to make it stop","Ignore it","Deny it and change that account's password","Reboot your phone"],2,"A surprise prompt means someone has your password. Deny it and change the password.")],
 widget=None))

